// 获取输入文本
const inputText = $input.first().json.output.title;

// 格式化文本函数 - 反向操作，只保留需要的字符
function formatText(text) {
  let cleanedText = text;

  // 1. 只保留中文、英文、数字、常用标点符号和空格
  // 这样可以有效去除所有emoji（包括复合emoji）
  cleanedText = cleanedText.replace(/[^\u4e00-\u9fff\u3400-\u4dbf\u3000-\u303f\uff00-\uffefa-zA-Z0-9\s.,!?;:()（）！？；：、。，]/g, '');

  // 2. 去除换行符，替换为空格
  cleanedText = cleanedText.replace(/\n+/g, ' ');

  // 3. 去除tag标签（#开头的词汇）
  cleanedText = cleanedText.replace(/#[^\s#]+/g, '');

  // 4. 去除单双引号
  cleanedText = cleanedText.replace(/['"]/g, '');

  // 5. 清理多余空格并修剪首尾空格
  cleanedText = cleanedText.replace(/\s+/g, ' ').trim();

  return cleanedText;
}

// 处理文本
const formattedText = formatText(inputText);

// 返回n8n格式的结果
return [
  {
    json: {
      formatted_text: formattedText,
      character_count: formattedText.length
    }
  }
];

