// 获取上游 AI Agent 输出的文本
const inputJson = $input.first().json;
const textContent = inputJson.output || JSON.stringify(inputJson);

let isLoggedIn = false;

// 1. 优先尝试提取与解析标准的 JSON 结构
try {
  // 匹配字符串中的 JSON 部分 (兼顾 ```json 代码块和纯 JSON)
  const jsonMatch = textContent.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsedData = JSON.parse(jsonMatch[0]);
    if (parsedData.isLogin !== undefined) {
      isLoggedIn = Boolean(parsedData.isLogin);
    } else if (parsedData.is_logged_in !== undefined) {
      isLoggedIn = Boolean(parsedData.is_logged_in);
    }
  }
} catch (e) {
  // 如果 JSON 解析失败，走降级流程
}

// 2. 如果未通过 JSON 提取到，使用关键词与正则保底匹配
if (!isLoggedIn) {
  isLoggedIn = /"isLogin"\s*:\s*true|'isLogin'\s*:\s*true|已处于|已登录|无需获取|成功登录/i.test(textContent);
}

let base64Image = '';

if (!isLoggedIn) {
  // 未登录时尝试提取 Base64 二维码
  const match = textContent.match(/data:image\/[a-zA-Z]+;base64,([a-zA-Z0-9+/=]+)/) || 
                textContent.match(/base64,([a-zA-Z0-9+/=]+)/);
  if (match && match[1]) {
    base64Image = match[1];
  }
}

return [{
  json: {
    isLogin: isLoggedIn,
    is_logged_in: isLoggedIn,
    base64_image: base64Image,
    file_name: 'xhs_login_qrcode.png',
    message: isLoggedIn ? '账号已登录，跳过二维码处理' : '获取二维码成功'
  }
}];

// 获取 HTTP Request 返回的 MCP 原始响应
const response = $input.first().json;

let base64Image = '';

// 解析 MCP 标准返回格式中的 content
if (response.result && response.result.content) {
  const imgItem = response.result.content.find(item => item.type === 'image');
  if (imgItem && imgItem.data) {
    base64Image = imgItem.data;
  }
}

return [{
  json: {
    base64_image: base64Image,
    file_name: 'xhs_login_qrcode.png'
  }
}];

const items = $input.first().json.response; // 数组，结构待你实测确认
let base64 = null;

// 情况一：内容块里有 type === 'image' 且带 data 字段
const imgBlock = items.find(i => i.type === 'image' && i.data);
if (imgBlock) {
  base64 = imgBlock.data;
} else {
  // 情况二：base64 混在 text 文本里，正则提取长字符串
  const textBlock = items.find(i => i.type === 'text');
  if (textBlock) {
    const match = textBlock.text.match(/[A-Za-z0-9+/=]{100,}/);
    if (match) base64 = match[0];
  }
}

if (base64 && base64.includes(',')) {
  base64 = base64.split(',')[1]; // 去掉 data:image/png;base64, 前缀
}

return [{
  json: {
    base64,
    fileName: `xhs_login_qrcode_${Date.now()}.png`,
    raw: items // 保留原始数据，方便你调试时对照
  }
}];
